# Surah Al-Isra (chapter 17) — part 11: ayat 101-110 (IDs 2130-2139)
SURAH = 17

ENTRIES = {
2130: (
"اور یقیناً ہم نے موسیٰؑ کو نو واضح معجزات دیے — پس بنی اسرائیل سے پوچھیے جب وہ ان کے پاس آئے تو فرعون نے ان سے کہا اے موسیٰ میں تو تمہیں جادو زدہ سمجھتا ہوں",
"""۱۔ موسیٰؑ کے نو معجزے؛ بنی اسرائیل کی تاریخ؛ فرعون کا اعتراض — آپ جادو زدہ ہیں۔
۲۔ ’’وَلَقَدْ آتَيْنَا مُوسَىٰ تِسْعَ آيَاتٍ بَيِّنَاتٍ فَاسْأَلْ بَنِي إِسْرَائِيلَ إِذْ جَاءَهُمْ فَقَالَ لَهُ فِرْعَوْنُ إِنِّي لَأَظُنُّكَ يَا مُوسَىٰ مَسْحُورًا‘‘ — اور یقیناً ہم نے موسیٰؑ کو نو واضح معجزات دیے — پس بنی اسرائیل سے پوچھیے جب وہ ان کے پاس آئے تو فرعون نے ان سے کہا اے موسیٰ میں تو تمہیں جادو زدہ سمجھتا ہوں — یعنی ہم نے موسیٰؑ کو نو واضح نشانیاں دیں — بنی اسرائیل سے پوچھو جب موسیٰؑ ان کے پاس آئے تو فرعون نے کہا اے موسیٰ میں تو تمہیں جادو زدہ سمجھتا ہوں۔
۳۔ عملی سبق: اللہ کے معجزات کو رد نہ کرو؛ بنی اسرائیل کی تاریخ سے سبق لو۔"""
),
2131: (
"موسیٰؑ نے کہا آپ کو معلوم ہے کہ ان نشانیوں کو آسمانوں اور زمین کے رب کے سوا کسی نے نازل نہیں کیا — اور اے فرعون میں سمجھتا ہوں کہ تو تباہ ہونے والا ہے",
"""۱۔ موسیٰؑ کا جواب: یہ معجزے اللہ کے ہیں؛ فرعون کا انجام تباہی۔
۲۔ ’’قَالَ لَقَدْ عَلِمْتَ مَا أَنزَلَ هَٰؤُلَاءِ إِلَّا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ بَصَائِرَ وَإِنِّي لَأَظُنُّكَ يَا فِرْعَوْنُ مَثْبُورًا‘‘ — موسیٰؑ نے کہا آپ کو معلوم ہے کہ ان نشانیوں کو آسمانوں اور زمین کے رب کے سوا کسی نے نازل نہیں کیا — اور اے فرعون میں سمجھتا ہوں کہ تو تباہ ہونے والا ہے — یعنی موسیٰؑ نے کہا آپ کو معلوم ہے کہ ان نشانیوں کو زمین و آسمان کے رب کے سوا کسی نے نازل نہیں کیا اور اے فرعون میں سمجھتا ہوں کہ تو ہلاک ہونے والا ہے۔
۳۔ عملی سبق: اللہ کے معجزات کا انکار نہ کرو؛ تکبر کا انجام تباہی ہے۔"""
),
2132: (
"پھر اس نے انہیں اس سرزمین سے اکھاڑ پھینکنے کا ارادہ کیا — پس ہم نے اسے اور اس کے ساتھیوں کو غرق کر دیا — اور ہم نے ان کے بعد بنی اسرائیل سے کہا کہ اس سرزمین میں سکونت کرو — پھر جب کہ آخرت کے وعدے کا وقت آئے گا تو ہم تمہیں اکٹھا لے آئیں گے",
"""۱۔ فرعون نے موسیٰؑ کو نکالنے کا منصوبہ بنایا؛ اللہ نے اسے غرق کر دیا؛ بنی اسرائیل کو زمین کا مالک بنایا۔
۲۔ ’’فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ الْأَرْضِ فَأَغْرَقْنَاهُ وَمَن مَّعَهُ جَمِيعًا وَقُلْنَا مِن بَعْدِهِ لِبَنِي إِسْرَائِيلَ اسْكُنُوا الْأَرْضَ فَإِذَا جَاءَ وَعْدُ الْآخِرَۃِ جِئْنَا بِكُمْ لَفِيفًا‘‘ — پھر اس نے انہیں اس سرزمین سے اکھاڑ پھینکنے کا ارادہ کیا — پس ہم نے اسے اور اس کے ساتھیوں کو غرق کر دیا — اور ہم نے ان کے بعد بنی اسرائیل سے کہا کہ اس سرزمین میں سکونت کرو — پھر جب کہ آخرت کے وعدے کا وقت آئے گا تو ہم تمہیں اکٹھا لے آئیں گے — یعنی فرعون نے بنی اسرائیل کو زمین سے نکالنے کا ارادہ کیا — پس ہم نے اسے اور اس کے ساتھیوں کو غرق کر دیا — اور ان کے بعد بنی اسرائیل سے کہا اس زمین میں آباد ہو جاؤ — پھر جب آخرت کا وعدہ آئے گا ہم تم سب کو اکٹھا کر کے لے آئیں گے۔
۳۔ عملی سبق: اللہ فرعون جیسے ظالموں کو بھی ہلاک کر دیتا ہے؛ ظالم کا انجام تباہی ہے۔"""
),
2133: (
"اور ہم نے قرآن کو حق کے ساتھ نازل کیا اور وہ حق پر مشتمل نازل ہوا — اور ہم نے آپ کو صرف خوشخبری دینے والا اور ڈرانے والا بنا کر بھیجا ہے",
"""۱۔ قرآن حق پر مبنی نازل ہوا؛ نبیؐ بشارت اور انذار ہیں؛ اس پر ایمان لاؤ۔
۲۔ ’’وَبِالْحَقِّ أَنزَلْنَاهُ وَبِالْحَقِّ نَزَلَ وَمَا أَرْسَلْنَاكَ إِلَّا مُبَشِّرًا وَنَذِيرًا‘‘ — اور ہم نے قرآن کو حق کے ساتھ نازل کیا اور وہ حق پر مشتمل نازل ہوا — اور ہم نے آپ کو صرف خوشخبری دینے والا اور ڈرانے والا بنا کر بھیجا ہے — یعنی ہم نے قرآن حق کے ساتھ نازل کیا اور وہ حق ہی پر نزولی ہوا — اور ہم نے آپ کو صرف خوشخبری دینے والا اور ڈرانے والا بنا کر بھیجا ہے۔
۳۔ عملی سبق: قرآن حق ہے؛ نبیؐ کے پیغام پر ایمان لاؤ؛ بشارت اور انذار دونوں پر یقین کرو۔"""
),
2134: (
"اور قرآن کا ایک ٹکڑوں میں نازل ہونا — تاکہ آپ اسے لوگوں کو ٹھہر ٹھہر کر پڑھ کر سنائیں — اور ہم نے اسے رفتہ رفتہ نازل کیا",
"""۱۔ قرآن ایک وقت میں نازل نہیں ہوا؛ تدریجی نزول — 23 سال میں؛ دل میں اترنے کے لیے۔
۲۔ ’’وَقُرْآنًا فَرَقْنَاهُ لِتَقْرَأَهُ عَلَى النَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَاهُ تَنزِيلًا‘‘ — اور قرآن کا ایک ٹکڑوں میں نازل ہونا — تاکہ آپ اسے لوگوں کو ٹھہر ٹھہر کر پڑھ کر سنائیں — اور ہم نے اسے رفتہ رفتہ نازل کیا — یعنی ہم نے قرآن کو الگ الگ حصوں میں اتارا تاکہ آپ اسے لوگوں کو وقفے وقفے سے پڑھ کر سنائیں اور ہم نے اسے بتدریج نازل کیا۔
۳۔ عملی سبق: قرآن آہستہ آہستہ پڑھو اور سمجھو؛ اس کی تلاوت ہر وقت ادای؛ رات میں تعجب کرو۔"""
),
2135: (
"کہیے اس پر ایمان لاؤ یا نہ لاؤ — یقیناً جنہیں آپ سے پہلے علم دیا گیا تھا وہ اسے سن کر سجدہ میں گر جاتے ہیں",
"""۱۔ قرآن کی حقیقت سے انکار نہ کرو؛ اہل علم قرآن سن کر سجدے میں گر جاتے تھے۔
۲۔ ’’قُلْ آمِنُوا بِهِ أَوْ لَا تُؤْمِنُوا إِنَّ الَّذِينَ أُوتُوا الْعِلْمَ مِن قَبْلِهِ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا‘‘ — کہیے اس پر ایمان لاؤ یا نہ لاؤ — یقیناً جنہیں آپ سے پہلے علم دیا گیا تھا وہ اسے سن کر سجدہ میں گر جاتے ہیں — یعنی کہہ دو اس پر ایمان لاؤ یا نہ لاؤ — جنہیں آپ سے پہلے علم دیا گیا تھا وہ اسے سن کر گھٹنوں کے بل گر پڑتے ہیں۔
۳۔ عملی سبق: قرآن سن کر خشوع سے سجدہ کرو؛ اہل علم کی طرح عمل کرو۔"""
),
2136: (
"اور وہ کہتے ہیں سبحان اللہ ہمارا رب کا وعدہ یقیناً پورا ہوتا ہے",
"""۱۔ اہل علم قرآن کی آیات سن کر کہتے ہیں ہمارا رب کا وعدہ ضرور پورا ہوتا ہے۔
۲۔ ’’وَيَقُولُونَ سُبْحَانَ رَبِّنَا إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا‘‘ — اور وہ کہتے ہیں سبحان اللہ ہمارا رب کا وعدہ یقیناً پورا ہوتا ہے — یعنی اور وہ کہتے ہیں ہمارا رب پاک ہے یقیناً ہمارا رب کے وعدے کو پورا کیا جانا ہے۔
۳۔ عملی سبق: اللہ کے وعدوں پر کامل بھروسا رکھو؛ قرآن پڑھ کر اس کی عظمت پر یقین کرو۔"""
),
2137: (
"اور وہ ٹھوڑیوں کے بل گر پڑتے ہیں روتے ہوئے — اور یہ ان کے خشوع میں اضافہ کرتا ہے",
"""۱۔ قرآن سن کر اہل علم خشوع اور گریاں سجدہ میں گرتے ہیں؛ یہ ایمان کی علامت ہے۔
۲۔ ’’وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا‘‘ — اور وہ ٹھوڑیوں کے بل گر پڑتے ہیں روتے ہوئے — اور یہ ان کے خشوع میں اضافہ کرتا ہے — یعنی وہ ٹھوڑیوں کے بل سجدہ میں گر پڑتے ہیں روتے ہوئے اور یہ ان کے خشوع میں اضافہ کرتا ہے۔
۳۔ عملی سبق: قرآن سن کر روئیں؛ خشوع حاصل کرو؛ یہ ایمان کی نشانی ہے۔"""
),
2138: (
"کہیے اللہ کو پکارو یا رحمان کو پکارو — جو بھی پکارو اس کے لیے بہترین نام ہیں — اور آپ اپنی نماز میں نہ زیادہ آواز سے پڑھیں اور نہ دھیمی آواز سے بلکہ ان دونوں کے درمیان کا راستہ تلاش کریں",
"""۱۔ اللہ کے تمام نام خوبصورت ہیں؛ نماز میں معتدل آواز سے قرآن پڑھو۔
۲۔ ’’قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَٰنَ أَيًّا مَّا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَىٰ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا‘‘ — کہیے اللہ کو پکارو یا رحمان کو پکارو — جو بھی پکارو اس کے لیے بہترین نام ہیں — اور آپ اپنی نماز میں نہ زیادہ آواز سے پڑھیں اور نہ دھیمی آواز سے بلکہ ان دونوں کے درمیان کا راستہ تلاش کریں — یعنی کہہ دو اللہ کو پکارو یا رحمان کو پکارو جو بھی نام اپنے رب کے لیے پکارو اس کے بہترین نام ہیں — اور آپ اپنی نماز میں نہ بالکل اونچی آواز سے پڑھیں اور نہ بالکل دھیمی آواز سے بلکہ دونوں کے درمیان کا راستہ اختیار کریں۔
۳۔ عملی سبق: اللہ کے ناموں میں سے کوئی بھی خوبصورت نام لو؛ نماز میں معتدل آواز رکھو۔"""
),
2139: (
"اور کہیے سب تعریف اللہ کے لیے ہے جس نے نہ کوئی بیٹا بنایا اور نہ اس کا کوئی شریک حکومت میں ہے اور نہ وہ کمزور ہو کر کسی حمایتی کا محتاج ہے — اور اس کی بڑائی کرو",
"""۱۔ اللہ ہر نسبت سے پاک ہے؛ تنہا معبود؛ اس کی بڑائی کرو۔
۲۔ ’’وَقُلِ الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا‘‘ — اور کہیے سب تعریف اللہ کے لیے ہے جس نے نہ کوئی بیٹا بنایا اور نہ اس کا کوئی شریک حکومت میں ہے اور نہ وہ کمزور ہو کر کسی حمایتی کا محتاج ہے — اور اس کی بڑائی کرو — یعنی کہہ دو سب تعریف اللہ کے لیے ہے جس نے نہ کوئی بیٹا بنایا اور نہ حکومت میں کوئی شریک ہے اور نہ وہ بزدلی سے کسی حمایتی کا محتاج ہے — اور اس کی عظمت بیان کرو۔
۳۔ عملی سبق: اللہ کی تعریف کرو؛ اس کی بڑائی کرو؛ وہ تنہا معبود ہے۔"""
),
}
